147	    public static <T> T doIt(Callable<T> xaction) throws Exception {
148	        resetRetries();
149	        while (true) {
150	            // Someday figure out how aborted transactions get this far...
151	            Transaction me = getTransaction();
152	            if (me != null && !me.isActive()) {
153	                throw new AbortedException(me, "Got to doit with an aborted current transaction");
154	            }
155	            try {
156	                T result = doItOnce(xaction);
157	                return result;
158	            }
159	            catch (OrphanedException oe) {
160	                if (oe.getTransaction() != null && oe.getTransaction() != me && oe.getTransaction().getParent() != me)
161	                    throw new RuntimeException(
162	                            Thread.currentThread().getName() + " OE transaction  = " + oe + " me = " + me +
163	                            " oe parent = " + oe.getTransaction().getParent());
164	            }
165	            catch (AbortedException ae) {
166	                if (ae.getTransaction() != null && ae.getTransaction() != me && ae.getTransaction().getParent() != me)
167	                    throw new RuntimeException(
168	                            Thread.currentThread().getName() + " AE transaction  = " + ae + " me = " + me +
169	                            " ae parent = " + ae.getTransaction().getParent());
170	            }
